import React, { createContext, useState, useEffect } from 'react';
import axios from 'axios';

export const AppContext = createContext();

export const AppProvider = ({ children }) => {
  const [map, setMap] = useState('');
  const [config, setConfig] = useState(null);
  const [mapKey, setMapKey] = useState(1);
  const [mapLayer, setMapLayer] = useState('');
  const [mapLegendData, setMapLegendData] = useState('');
  const [mapData, setMapData] = useState({ label: "", varible: "", type: "", style: "" });
  const [zoom, setZoom] = useState(7);
  const [center, setCenter] = useState([-1.831239, -78.183406]);
  const [geom, setGeom] = useState('');
  const [loadMapOption, setLoadMapOption] = useState('');  

  useEffect(() => {
    const fetchConfig = async () => {
      const response = await axios.get('./config.json');
      setConfig(response.data);
    };
    fetchConfig();
  }, []);

  return (
    <AppContext.Provider value={{
      map, setMap,
      config, setConfig,
      mapKey, setMapKey,
      mapLayer, setMapLayer,
      mapLegendData, setMapLegendData,
      mapData, setMapData,
      zoom, setZoom,
      center, setCenter,
      geom, setGeom,
      loadMapOption, setLoadMapOption,
    }}>
      {children}
    </AppContext.Provider>
  );
};
