import { useState, useEffect } from 'react'
import { fetchSearchOptions } from '../helpers/fetchSearchOptions';

export const useFetchSearch = ( geoserverUrl, layerName, variableName, setLoadMapOption ) => {

    const [searchOptions, setSearchOptions] = useState('');
    
    useEffect( () => {
        fetchSearchOptions( geoserverUrl, layerName, variableName )
            .then( data => {                
                setSearchOptions(data);
                setLoadMapOption(false)
            })
    }, [layerName])
    return searchOptions;
}